  col = mix(col, crimson,  smoothstep(0.20, 0.44, temp));
  col = mix(col, orange,   smoothstep(0.40, 0.72, temp));
  col = mix(col, gold,     smoothstep(0.68, 0.96, temp));
  col = mix(col, whiteHot, smoothstep(0.94, 1.30, temp));
